const testVariantPTX = `//
// Generated by NVIDIA NVVM Compiler
//
.version 8.8
.target sm_121a
.visible .entry ds4_rms(
	.param .u64 x
)
{
	.reg .f32 %f<4>;
	ld.param.u64 	%rd1, [x];
	div.rn.f32 	%f1, %f2, %f3;
	@%p1 bra 	$L__BB0_2;
	sqrt.rn.f32 	%f2, %f1;
$L__BB0_2:
	ret;
}
`

const testVariantSASS = `	Function : ds4_rms
/*0000*/                   LDG.E R0, [R2.64] ;
/*0010*/                   MUFU.RCP R3, R0 ;
/*0020*/                   FCHK P0, R0, R1 ;
/*0030*/                   RET ;
`

func TestCountPTXOpcodes(t *testing.T) {
	got := countPTXOpcodes(testVariantPTX)
	want := map[string]int{
		"ld.param.u64": 1,
		"div.rn.f32":   1,
		"bra":          1,
		"sqrt.rn.f32":  1,
		"ret":          1,
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("countPTXOpcodes() = %v, want %v", got, want)
	}
}

func TestCountSASSOpcodes(t *testing.T) {
	opcodes, kernels := countSASSOpcodes(testVariantSASS)
	if opcodes["MUFU.RCP"] != 1 || opcodes["FCHK"] != 1 {
		t.Errorf("countSASSOpcodes() opcodes = %v, want MUFU.RCP and FCHK", opcodes)
	}
	if kernels["ds4_rms"] != 4 {
		t.Errorf("countSASSOpcodes() kernels = %v, want ds4_rms: 4", kernels)
	}
	if opcodes, kernels := countSASSOpcodes(""); len(opcodes) != 0 || len(kernels) != 0 {
		t.Errorf("countSASSOpcodes(\"\") = %v, %v, want empty", opcodes, kernels)
	}
}

func TestParseVariantOptions(t *testing.T) {
	tests := []struct {
		name      string
		in        string
		want      []string
		recompile bool
	}{
		{"empty", "  ", nil, false},
		{"capture", "capture", nil, false},
		{"one", "--use_fast_math", []string{"--use_fast_math"}, true},
		{"several", " --gpu-architecture=sm_121a  --use_fast_math ", []string{"--gpu-architecture=sm_121a", "--use_fast_math"}, true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, recompile := parseVariantOptions(tt.in)
			if !reflect.DeepEqual(got, tt.want) || recompile != tt.recompile {
				t.Errorf("parseVariantOptions(%q) = %v, %v, want %v, %v", tt.in, got, recompile, tt.want, tt.recompile)
			}
		})
	}
}

func TestDiffVariants(t *testing.T) {
	a := &nvrtcVariant{Label: "capture", Stats: variantStats{
		PTXInstructions:  10,
		SASSInstructions: 100,
		Kernels:          map[string]int{"ds4_rms": 60, "ds4_hc_post": 40},
		SASSOpcodes:      map[string]int{"FCHK": 12, "MUFU.RCP": 8, "FFMA": 30},
	}}
	b := &nvrtcVariant{Label: "--use_fast_math", Stats: variantStats{
		PTXInstructions:  9,
		SASSInstructions: 70,
		Kernels:          map[string]int{"ds4_rms": 30, "ds4_hc_post": 40},
		SASSOpcodes:      map[string]int{"FCHK": 0, "MUFU.RCP": 6, "FFMA": 30},
	}}

	got := diffVariants(a, b)
	want := []variantDelta{
		{Group: "total", Name: "PTX instructions", A: 10, B: 9, Delta: -1},
		{Group: "total", Name: "SASS instructions", A: 100, B: 70, Delta: -30},
		{Group: "kernel", Name: "ds4_rms", A: 60, B: 30, Delta: -30},
		{Group: "sass", Name: "FCHK", A: 12, B: 0, Delta: -12},
		{Group: "sass", Name: "MUFU.RCP", A: 8, B: 6, Delta: -2},
	}
	if !reflect.DeepEqual(got, want) {
		t.Errorf("diffVariants() = %+v, want %+v", got, want)
	}
	if diffVariants(nil, b) != nil {
		t.Error("diffVariants(nil, b) = non-nil, want nil")
	}
}

func TestNewVariantStats(t *testing.T) {
	s := newVariantStats(testVariantPTX, testVariantSASS)
	if s.PTXInstructions != 5 {
		t.Errorf("PTXInstructions = %d, want 5", s.PTXInstructions)
	}
	if s.SASSInstructions != 4 {
		t.Errorf("SASSInstructions = %d, want 4", s.SASSInstructions)
	}
	if s.Kernels["ds4_rms"] != 4 {
		t.Errorf("Kernels = %v, want ds4_rms: 4", s.Kernels)
	}
}

func TestRecompileHandler(t *testing.T) {
	src := &recompileSource{
		Name:    "ds4_math.cu",
		File:    "ds4_math.cu",
		Arch:    "sm_121a",
		Options: []string{"--gpu-architecture=sm_121a", "--generate-line-info"},
		Source:  "extern \"C\" __global__ void ds4_rms(float *x) {}",
		PTX:     testVariantPTX,
		SASS:    testVariantSASS,
	}
	var gotOptions []string
	compile := func(name, source string, options []string) *nvrtcVariant {
		gotOptions = options
		if name != src.File || source != src.Source {
			t.Errorf("compile(%q, %q, ...), want (%q, %q)", name, source, src.File, src.Source)
		}
		// One MUFU.RCP fewer and no FCHK, as fast math removes the check.
		return &nvrtcVariant{
			Label:   strings.Join(options, " "),
			Options: options,
			SASS:    "\tFunction : ds4_rms\n/*0000*/ LDG.E R0, [R2.64] ;\n/*0010*/ MUFU.RCP R3, R0 ;\n/*0020*/ RET ;\n",
			Stats:   newVariantStats("", "\tFunction : ds4_rms\n/*0000*/ LDG.E R0, [R2.64] ;\n/*0010*/ MUFU.RCP R3, R0 ;\n/*0020*/ RET ;\n"),
		}
	}

	handler := newRecompileHandler([]*recompileSource{src}, compile)
	req := httptest.NewRequest("GET", "/api/recompile?a=capture&b=--gpu-architecture%3Dsm_121a+--use_fast_math", nil)
	rec := httptest.NewRecorder()
	handler(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want %d: %s", rec.Code, http.StatusOK, rec.Body.String())
	}
	var resp recompileResponse
	if err := json.NewDecoder(rec.Body).Decode(&resp); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	if want := []string{"--gpu-architecture=sm_121a", "--use_fast_math"}; !reflect.DeepEqual(gotOptions, want) {
		t.Errorf("compiled with %v, want %v", gotOptions, want)
	}
	if resp.A.Label != captureVariantLabel || resp.A.Stats.SASSInstructions != 4 {
		t.Errorf("A = %+v, want the capture's own artifacts", resp.A)
	}
	if resp.B.Stats.SASSInstructions != 3 {
		t.Errorf("B SASS instructions = %d, want 3", resp.B.Stats.SASSInstructions)
	}
	if resp.Caveat == "" {
		t.Error("response carries no static-count caveat")
	}
	var fchk bool
	for _, d := range resp.Deltas {
		if d.Group == "sass" && d.Name == "FCHK" {
			fchk = true
			if d.A != 1 || d.B != 0 || d.Delta != -1 {
				t.Errorf("FCHK row = %+v, want 1 -> 0", d)
			}
		}
	}
	if !fchk {
		t.Error("deltas report no FCHK change")
	}
}

func TestPipelineServerServesNVRTCPanel(t *testing.T) {
	cap, _ := createTest5TierCapture(t)
	data, err := buildPipelineViewData(cap, "capture.pprof", "")
	if err != nil {
		t.Fatalf("buildPipelineViewData: %v", err)
	}
	if len(data.Recompile) != 1 || data.Recompile[0].Source == "" {
		t.Fatalf("capture with CUDA C++ source produced %d recompile sources, want 1", len(data.Recompile))
	}
	if want := []string{"--gpu-architecture=sm_121a", "--generate-line-info", "--use_fast_math"}; !reflect.DeepEqual(data.Recompile[0].Suggested, want) {
		t.Errorf("Suggested = %v, want %v", data.Recompile[0].Suggested, want)
	}

	handler := newPipelineServerHandler(data)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("GET", "/", nil))
	if !strings.Contains(rec.Body.String(), "nvrtcPanel") || !strings.Contains(rec.Body.String(), "--use_fast_math") {
		t.Error("served page offers no NVRTC flag panel")
	}

	// Both sides name the capture, so the route answers without compiling.
	rec = httptest.NewRecorder()
	handler.ServeHTTP(rec, httptest.NewRequest("GET", "/api/recompile?a=capture&b=capture", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("/api/recompile status = %d, want %d: %s", rec.Code, http.StatusOK, rec.Body.String())
	}
	var resp recompileResponse
	if err := json.NewDecoder(rec.Body).Decode(&resp); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	if len(resp.Deltas) != 2 || resp.Deltas[0].Delta != 0 || resp.Deltas[1].Delta != 0 {
		t.Errorf("capture compared against itself reports %+v, want zero deltas", resp.Deltas)
	}
}

func TestRecompileHandlerWithoutSource(t *testing.T) {
	handler := newRecompileHandler([]*recompileSource{{Name: "kernels.cu", File: "kernels.cu"}}, func(string, string, []string) *nvrtcVariant {
		t.Error("compiled a capture that retained no source")
		return nil
	})
	rec := httptest.NewRecorder()
	handler(rec, httptest.NewRequest("GET", "/api/recompile?a=capture&b=--use_fast_math", nil))
	if rec.Code != http.StatusNotFound {
		t.Errorf("status = %d, want %d", rec.Code, http.StatusNotFound)
	}
}

func TestAssumedOptions(t *testing.T) {
	const headerless = "extern \"C\" __global__ void k() {}"
	if got, want := assumedOptions("sm_121a", headerless), []string{"--gpu-architecture=sm_121a", "--generate-line-info"}; !reflect.DeepEqual(got, want) {
		t.Errorf("assumedOptions(sm_121a, headerless) = %v, want %v", got, want)
	}
	if got, want := assumedOptions("", headerless), []string{"--generate-line-info"}; !reflect.DeepEqual(got, want) {
		t.Errorf("assumedOptions(\"\", headerless) = %v, want %v", got, want)
	}

	// A source that includes a header needs an include path: NVRTC searches no
	// directory unless told to. The option appears only where a toolkit is
	// installed, so the assertion follows cudaIncludeDir.
	got := assumedOptions("sm_121a", "#include <cuda_fp16.h>\n"+headerless)
	var havePath bool
	for _, opt := range got {
		havePath = havePath || strings.HasPrefix(opt, "--include-path=")
	}
	if want := cudaIncludeDir() != ""; havePath != want {
		t.Errorf("assumedOptions with a header = %v, include path present = %v, want %v", got, havePath, want)
	}
}

func TestMissingIncludeHint(t *testing.T) {
	// The log NVRTC 13.0 writes on the DGX for a source including cuda_fp16.h
	// with no include path. nvcc compiles the same source, because it knows its
	// own toolkit include directory.
	const log = `fp16.cu(1): catastrophic error: could not open source file "cuda_fp16.h" (no directories in search list)`
	hint := missingIncludeHint(log)
	if !strings.Contains(hint, "--include-path=") {
		t.Errorf("missingIncludeHint(%q) = %q, want an --include-path= remedy", log, hint)
	}
	if got := missingIncludeHint("error: identifier \"foo\" is undefined"); got != "" {
		t.Errorf("missingIncludeHint(unrelated error) = %q, want \"\"", got)
	}
}

func TestRecompileSourcesPerModule(t *testing.T) {
	// A capture of a program like ds4-min: modules compiled separately, with
	// different options, only some of them recorded.
	cap := &cudacapture.Capture{
		Files: map[string][]byte{
			"ds4_math.cu":       []byte("extern \"C\" __global__ void ds4_rms(float *x) {}"),
			"ds4_math.sass":     []byte(testVariantSASS),
			"ds4_quant_q8_0.cu": []byte("extern \"C\" __global__ void ds4_quant(float *x) {}"),
			"ds4_probe.cu":      []byte(""),
		},
		Modules: []cudacapture.Module{
			{ID: "1", Name: "ds4_math", Code: cudacapture.CodeFiles{Source: "ds4_math.cu", SASS: "ds4_math.sass"}},
			{ID: "2", Name: "ds4_quant_q8_0", Code: cudacapture.CodeFiles{Source: "ds4_quant_q8_0.cu"}},
			{ID: "3", Name: "ds4_probe", Code: cudacapture.CodeFiles{Source: "ds4_probe.cu"}},
		},
	}
	recorded := map[string][]string{
		"ds4_quant_q8_0": {"--gpu-architecture=sm_121a", "--generate-line-info", "--use_fast_math"},
	}

	got := recompileSources(cap, "sm_121a", recorded)
	if len(got) != 2 {
		t.Fatalf("recompileSources() returned %d sources, want 2 (the empty module is dropped)", len(got))
	}
	if got[0].Name != "ds4_math" || got[0].Recorded {
		t.Errorf("first source = %+v, want ds4_math with assumed options", got[0])
	}
	if got[0].SASS != testVariantSASS {
		t.Error("first source did not pick up its own module's SASS")
	}
	if !got[1].Recorded || !reflect.DeepEqual(got[1].Options, recorded["ds4_quant_q8_0"]) {
		t.Errorf("second source = %+v, want the recorded --use_fast_math options", got[1])
	}
	// The recorded module already compiles with fast math, so the panel must
	// not suggest it again: that would compare a variant against itself.
	if !reflect.DeepEqual(got[1].Suggested, got[1].Options) {
		t.Errorf("suggested for a fast-math module = %v, want its own options %v", got[1].Suggested, got[1].Options)
	}
	if n := strings.Count(strings.Join(got[0].Suggested, " "), "--use_fast_math"); n != 1 {
		t.Errorf("suggested for a plain module = %v, want one --use_fast_math", got[0].Suggested)
	}

	if src := findRecompileSource(got, "ds4_quant_q8_0"); src != got[1] {
		t.Errorf("findRecompileSource(name) = %+v, want the second source", src)
	}
	if src := findRecompileSource(got, "1"); src != got[0] {
		t.Errorf("findRecompileSource(id) = %+v, want the first source", src)
	}
	if src := findRecompileSource(got, "absent"); src != nil {
		t.Errorf("findRecompileSource(absent) = %+v, want nil", src)
	}
}

func TestRecompileSourcesFallsBackToCaptureCode(t *testing.T) {
	cap := &cudacapture.Capture{
		Files: map[string][]byte{"kernels.cu": []byte("extern \"C\" __global__ void k() {}")},
	}
	got := recompileSources(cap, "sm_121a", nil)
	if len(got) != 1 || got[0].File != "kernels.cu" {
		t.Fatalf("recompileSources() = %+v, want one source from kernels.cu", got)
	}
	if got[0].Recorded {
		t.Error("a capture that records no options reported recorded options")
	}
}

// TestRecompileHandlerFailedVariant is the defect a bogus flag exposed: a
// variant that fails to compile has zero counts, and diffing against them
// renders the failure as every instruction disappearing, the largest
// improvement the table can show.
func TestRecompileHandlerFailedVariant(t *testing.T) {
	src := &recompileSource{
		Name:   "ds4_math.cu",
		File:   "ds4_math.cu",
		Source: "extern \"C\" __global__ void ds4_rms(float *x) {}",
		PTX:    testVariantPTX,
		SASS:   testVariantSASS,
	}
	compile := func(name, source string, options []string) *nvrtcVariant {
		return &nvrtcVariant{
			Label:   strings.Join(options, " "),
			Options: options,
			Error:   "nvrtc: NVRTC_ERROR_INVALID_OPTION",
		}
	}
	handler := newRecompileHandler([]*recompileSource{src}, compile)
	rec := httptest.NewRecorder()
	handler(rec, httptest.NewRequest("GET", "/api/recompile?a=capture&b=--not-a-flag", nil))
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want %d: %s", rec.Code, http.StatusOK, rec.Body.String())
	}
	var resp recompileResponse
	if err := json.NewDecoder(rec.Body).Decode(&resp); err != nil {
		t.Fatalf("decode response: %v", err)
	}
	if len(resp.Deltas) != 0 {
		t.Errorf("failed variant produced %d deltas, want none: %+v", len(resp.Deltas), resp.Deltas)
	}
	if resp.Note == "" {
		t.Error("response carries no note saying why there is no comparison")
	}
	if !strings.Contains(resp.Note, "NVRTC_ERROR_INVALID_OPTION") {
		t.Errorf("note = %q, want it to carry the compiler error", resp.Note)
	}
	if resp.B.Error == "" {
		t.Error("B reports no error")
	}
}

func TestIncomparable(t *testing.T) {
	ok := &nvrtcVariant{Label: "capture", Stats: newVariantStats(testVariantPTX, testVariantSASS)}
	bad := &nvrtcVariant{Label: "--not-a-flag", Error: "boom"}
	tests := []struct {
		name string
		a, b *nvrtcVariant
		want bool // want a comparison
	}{
		{"both ok", ok, ok, true},
		{"a failed", bad, ok, false},
		{"b failed", ok, bad, false},
		{"b missing", ok, nil, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := incomparable(tt.a, tt.b) == ""
			if got != tt.want {
				t.Errorf("comparable = %v, want %v (%q)", got, tt.want, incomparable(tt.a, tt.b))
			}
			if deltas := diffVariants(tt.a, tt.b); (len(deltas) > 0) != tt.want {
				t.Errorf("diffVariants returned %d rows, want comparable=%v", len(deltas), tt.want)
			}
		})
	}
}

// TestStaticExportOmitsNVRTC checks that an exported page carries no trace of
// the panel. The panel needs the live server to compile, so a static page that
// mentions it at all is offering something it cannot do.
func TestStaticExportOmitsNVRTC(t *testing.T) {
	data := &PipelineViewData{
		CaptureFile:  "static.pprof",
		Architecture: "sm_121",
		Recompile:    nil,
	}
	var buf bytes.Buffer
	if err := renderPipelineHTML(&buf, data); err != nil {
		t.Fatalf("renderPipelineHTML: %v", err)
	}
	for _, s := range []string{"nvrtcPanel", "nvrtcModule", "runRecompile", "/api/recompile"} {
		if bytes.Contains(buf.Bytes(), []byte(s)) {
			t.Errorf("static export mentions %q", s)
		}
	}
}

// TestRenderMultipleRecompileModules covers the shape the live capture cannot
// exercise: it holds one module, so the panel's module select is never really
// populated with a choice. Each option has to carry its own options, because
// modules in one capture need not have been compiled alike.
func TestRenderMultipleRecompileModules(t *testing.T) {
	data := &PipelineViewData{
		CaptureFile:  "two.pprof",
		Architecture: "sm_121",
		Recompile: []*recompileSource{
			{ID: "m0", Name: "ds4_math.cu", File: "ds4_math.cu", Recorded: true,
				Options:   []string{"--gpu-architecture=sm_121", "--generate-line-info"},
				Suggested: []string{"--gpu-architecture=sm_121", "--generate-line-info", "--use_fast_math"},
				Source:    "extern \"C\" __global__ void a() {}"},
			{ID: "m1", Name: "ds4_probe.cu", File: "ds4_probe.cu", Recorded: false,
				Options:   []string{"--gpu-architecture=compute_121"},
				Suggested: []string{"--gpu-architecture=compute_121", "--use_fast_math"},
				Source:    "extern \"C\" __global__ void b() {}"},
		},
	}
	var buf bytes.Buffer
	if err := renderPipelineHTML(&buf, data); err != nil {
		t.Fatalf("renderPipelineHTML: %v", err)
	}
	html := buf.String()
	if got := strings.Count(html, `<option value="m`); got != 2 {
		t.Errorf("rendered %d module options, want 2", got)
	}
	// The two differ in target kind, virtual against physical. An option that
	// carried the other module's flags would recompile the wrong thing.
	for _, want := range []string{
		`value="m0" data-options="--gpu-architecture=sm_121 --generate-line-info"`,
		`value="m1" data-options="--gpu-architecture=compute_121"`,
		`data-recorded="true"`,
		`data-recorded="false"`,
	} {
		if !strings.Contains(html, want) {
			t.Errorf("rendered HTML lacks %s", want)
		}
	}
}
